const callbackQuery = $input.first().json.callback_query;
const chatIdGerente = callbackQuery.message.chat.id;
const messageId = callbackQuery.message.message_id;
const callbackData = callbackQuery.data;

let accion = '';
let quoteId = '';

// Formato 1: "approve_1bnknen" (con guion bajo)
if (callbackData.includes('approve_')) {
  accion = 'approve';
  quoteId = callbackData.split('approve_')[1];
}
// Formato 2: "reject_1bnknen" (con guion bajo)
else if (callbackData.includes('reject_')) {
  accion = 'reject';
  quoteId = callbackData.split('reject_')[1];
}
// Formato 3: "approve 1bnknen" (con espacio - el que tenés ahora)
else if (callbackData.includes('approve ')) {
  accion = 'approve';
  quoteId = callbackData.split('approve ')[1];
}
// Formato 4: "reject 1bnknen" (con espacio)
else if (callbackData.includes('reject ')) {
  accion = 'reject';
  quoteId = callbackData.split('reject ')[1];
}
// Fallback: split por guion bajo
else {
  const parts = callbackData.split('_');
  accion = parts[0].trim();
  quoteId = parts[1] || '';
}

// Limpiar espacios en blanco
accion = accion.trim();
quoteId = quoteId.trim();

const esAprobacion = accion === 'approve';
const nuevoStatus = esAprobacion ? 'APPROVED_BY_HUMAN' : 'REJECTED_BY_HUMAN';
const mensajeRespuesta = esAprobacion 
  ? '✅ Pedido APROBADO manualmente. Esperando confirmación del cliente.' 
  : '❌ Pedido RECHAZADO manualmente. El cliente será notificado.';

return [{
  json: {
    quote_id: quoteId,
    chat_id_gerente: chatIdGerente,
    message_id: messageId,
    accion: accion,
    es_aprobacion: esAprobacion,
    nuevo_status: nuevoStatus,
    mensaje_respuesta: mensajeRespuesta,
    callback_data_original: callbackData
  }
}];

const datosCliente = $('Obtener datos del cliente').item.json;
const accion = $('Parsear Callback').item.json.accion;
const quoteId = $('Parsear Callback').item.json.quote_id;

let productos = datosCliente.productos || datosCliente.pedido?.productos || [];
if (typeof productos === 'string') { try { productos = JSON.parse(productos); } catch (e) { productos = []; } }
if (!Array.isArray(productos)) productos = [];

let totalFinal = Number(datosCliente.total_final) || 0;
if (!totalFinal && productos.length > 0) totalFinal = productos.reduce((suma, p) => suma + (Number(p.subtotal) || 0), 0);
const plazoPago = datosCliente.plazo_pago || datosCliente.pedido?.plazo_pago || 'N/A';

const productosTexto = productos.length > 0
  ? productos.map(p => `SKU: ${p.sku} | Cant: ${p.cantidad} | Precio: $${p.precio_unit} | Desc: ${p.descuento_pct}% | Subtotal: $${p.subtotal}`).join('\n')
  : 'No disponible';

let textoCondiciones;
if (productos.length > 0 && totalFinal > 0) {
  textoCondiciones = `📦 ${productosTexto}\n💰 *Total:* $${totalFinal}\n📅 *Plazo de pago:* ${plazoPago}`;
} else {
  textoCondiciones = `📋 *Estado:* el pedido no pudo estructurarse automáticamente y pasó a revisión manual.\nUn ejecutivo de ventas te contactará con la cotización final.`;
}

return [{
  json: {
    quote_id: quoteId, chat_id: datosCliente.chat_id, sku_productos: productosTexto, total: totalFinal,
    plazo_pago: plazoPago, status: 'Aprobado por Gerencia', dictamen_juez: `Aprobación manual por gerente. Acción: ${accion}`,
    fecha_creacion: new Date().toISOString(), texto_condiciones: textoCondiciones
  }
}];
